<p>
<script>
setTimeout(function() {
    function getVal_v2(id) {
        let el = document.getElementById(id);
        if (!el) return 0;
        let val = parseFloat(el.value);
        return isNaN(val) ? 0 : val;
    }

    function renderMath_v2(container) {
        if (typeof MathJax !== 'undefined') {
            if (MathJax.typesetPromise) {
                MathJax.typesetPromise([container]);
            } else if (MathJax.Hub) {
                MathJax.Hub.Queue(["Typeset", MathJax.Hub, container]);
            }
        }
    }

    function formatNumber_v2(num) {
        return num < 0 ? `(${num})` : num;
    }

    let btnCalc_v2 = document.getElementById('dp-btn-calc_v2');
    let btnClear_v2 = document.getElementById('dp-btn-clear_v2');

    if (btnCalc_v2) {
        btnCalc_v2.onclick = function() {
            let ux = getVal_v2('dp-ux_v2'), uy = getVal_v2('dp-uy_v2'), uz = getVal_v2('dp-uz_v2');
            let vx = getVal_v2('dp-vx_v2'), vy = getVal_v2('dp-vy_v2'), vz = getVal_v2('dp-vz_v2');

            let modU2 = ux*ux + uy*uy + uz*uz;
            let modV2 = vx*vx + vy*vy + vz*vz;
            let dot = ux*vx + uy*vy + uz*vz;

            let resBox = document.getElementById('dp-result-container_v2');
            let boxMod = document.getElementById('dp-res-modulos_v2');
            let boxEsc = document.getElementById('dp-res-escalar_v2');
            let boxAng = document.getElementById('dp-res-angulo_v2');

            let uStr = formatNumber_v2(ux);
            let uyStr = formatNumber_v2(uy);
            let uzStr = formatNumber_v2(uz);
            let vStr = formatNumber_v2(vx);
            let vyStr = formatNumber_v2(vy);
            let vzStr = formatNumber_v2(vz);

            let mathModU = `\\[ |\\vec{u}| = \\sqrt{${uStr}^2 + ${uyStr}^2 + ${uzStr}^2} = \\sqrt{${modU2}}`;
            if (Math.sqrt(modU2) % 1 === 0) { mathModU += ` = ${Math.sqrt(modU2)}`; }
            mathModU += ` \\]`;

            let mathModV = `\\[ |\\vec{v}| = \\sqrt{${vStr}^2 + ${vyStr}^2 + ${vzStr}^2} = \\sqrt{${modV2}}`;
            if (Math.sqrt(modV2) % 1 === 0) { mathModV += ` = ${Math.sqrt(modV2)}`; }
            mathModV += ` \\]`;

            boxMod.innerHTML = `<p style="margin:0; text-align:left;"><strong>1. Cálculo de Módulos:</strong></p>` + mathModU + mathModV;

            let mathDot = `\\[ \\vec{u} \\bullet \\vec{v} = ${uStr} \\cdot ${vStr} + ${uyStr} \\cdot ${vyStr} + ${uzStr} \\cdot ${vzStr} = ${dot} \\]`;
            boxEsc.innerHTML = `<p style="margin:0; text-align:left;"><strong>2. Producto Escalar:</strong></p>` + mathDot;

            let mathAng = `<p style="margin:0; text-align:left;"><strong>3. Ángulo entre vectores (&alpha;):</strong></p>`;
            if (modU2 === 0 || modV2 === 0) {
                mathAng += `\\[ \\text{Indeterminado (uno de los vectores es el vector nulo).} \\]`;
            } else {
                let modU = Math.sqrt(modU2);
                let modV = Math.sqrt(modV2);
                let cosAlpha = dot / (modU * modV);
                cosAlpha = Math.max(-1, Math.min(1, cosAlpha));
                let angleRad = Math.acos(cosAlpha);
                let angleDeg = angleRad * (180 / Math.PI);

                let deg = Math.floor(angleDeg);
                let minFloat = (angleDeg - deg) * 60;
                let min = Math.floor(minFloat);
                let sec = Math.round((minFloat - min) * 60);
                if (sec === 60) { sec = 0; min += 1; }
                if (min === 60) { min = 0; deg += 1; }

                let valU = (modU % 1 === 0) ? modU : `\\sqrt{${modU2}}`;
                let valV = (modV % 1 === 0) ? modV : `\\sqrt{${modV2}}`;
                let prodInt = Math.sqrt(modU2 * modV2);
                let valProd = (prodInt % 1 === 0) ? prodInt : `\\sqrt{${modU2 * modV2}}`;

                mathAng += `\\[ \\cos(\\alpha) = \\dfrac{\\vec{u} \\bullet \\vec{v}}{|\\vec{u}| \\cdot |\\vec{v}|} = \\dfrac{${dot}}{${valU} \\cdot ${valV}} \\]`;
                mathAng += `\\[ \\alpha = \\arccos\\left( \\dfrac{${dot}}{${valProd}} \\right) \\approx ${angleDeg.toFixed(2)}^\\circ \\]`;
                mathAng += `\\[ \\alpha = ${deg}^\\circ\\ ${min}'\\ ${sec}'' \\]`;
            }
            boxAng.innerHTML = mathAng;

            resBox.style.display = 'block';
            renderMath_v2(resBox);
        };
    }

    if (btnClear_v2) {
        btnClear_v2.onclick = function() {
