<div style="white-space: nowrap;"><input type="number" id="al_s_g_a1" class="al-inp" />\(x +\) <input type="number" id="al_s_g_b1" class="al-inp" />\(y +\) <input type="number" id="al_s_g_c1" class="al-inp" />\(z +\) <input type="number" id="al_s_g_d1" class="al-inp" />\(= 0\)</div>
