<style>
    /* Blindaje CSS */
    #al-wrapper .al-inp { width: 48px !important; padding: 6px 4px !important; text-align: center !important; border: 2px solid #ffb74d !important; border-radius: 4px !important; font-size: 1em !important; background-color: #fff !important; color: #333 !important; transition: border-color 0.2s !important; margin: 0 2px !important; }
    #al-wrapper .al-inp:focus { outline: none !important; border-color: #e65100 !important; background-color: #fff3e0 !important; }
    #al-wrapper .al-select { padding: 6px 10px !important; font-size: 1em !important; border: 2px solid #ffb74d !important; border-radius: 4px !important; background-color: #fff !important; color: #e65100 !important; font-weight: bold !important; cursor: pointer !important; outline: none !important; }
    #al-wrapper .al-select:focus { border-color: #e65100 !important; }

    #al-wrapper .al-btn-calc { display: inline-block; background-color: #f57c00 !important; color: #ffffff !important; border: 2px solid #f57c00 !important; padding: 10px 22px !important; cursor: pointer !important; border-radius: 5px !important; font-weight: bold !important; font-size: 1.05em !important; margin: 0 5px !important; user-select: none; transition: all 0.2s !important; }
    #al-wrapper .al-btn-calc:hover { background-color: #e65100 !important; border-color: #e65100 !important; }

    #al-wrapper .al-btn-clear { display: inline-block; background-color: #ffffff !important; color: #f57c00 !important; border: 2px solid #f57c00 !important; padding: 10px 15px !important; cursor: pointer !important; border-radius: 5px !important; font-weight: bold !important; font-size: 1.05em !important; margin: 0 5px !important; user-select: none; transition: all 0.2s !important; }
    #al-wrapper .al-btn-clear:hover { background-color: #fff3e0 !important; border-color: #e65100 !important; color: #e65100 !important; }
</style>
<p>
<script>
(function() {
    function bindEvents() {
        // Gestión de los selectores para mostrar/ocultar inputs
        function setupSelect(selId, prefix) {
            let sel = document.getElementById(selId);
            if(sel) {
                sel.addEventListener('change', function(e) {
                    document.getElementById(prefix + 'vec').style.display = 'none';
                    document.getElementById(prefix + 'par').style.display = 'none';
                    document.getElementById(prefix + 'gen').style.display = 'none';
                    document.getElementById(prefix + e.target.value).style.display = 'flex';
                });
            }
        }
        setupSelect('al_sel_r', 'al_r_');
        setupSelect('al_sel_s', 'al_s_');

        let btnCalc = document.getElementById('al_btn_calc');
        let btnClear = document.getElementById('al_btn_clear');

        function getVal(id) {
            let el = document.getElementById(id);
            if (!el || el.value.trim() === '') return 0;
            let val = parseFloat(el.value);
            return isNaN(val) ? 0 : val;
        }

        function renderMath(container) {
            if (typeof MathJax !== 'undefined') {
                if (MathJax.typesetPromise) {
                    MathJax.typesetPromise([container]);
                } else if (MathJax.Hub) {
                    MathJax.Hub.Queue(["Typeset", MathJax.Hub, container]);
                }
            }
        }

        // Extrae el vector director (ignora los puntos ya que no afectan al ángulo)
        function getDir(prefix) {
            let type = document.getElementById('al_sel_' + prefix).value;
            if (type === 'vec') {
                return [ getVal('al_' + prefix + '_vx'), getVal('al_' + prefix + '_vy'), getVal('al_' + prefix + '_vz') ];
            } else if (type === 'par') {
                return [ getVal('al_' + prefix + '_par_vx'), getVal('al_' + prefix + '_par_vy'), getVal('al_' + prefix + '_par_vz') ];
            } else if (type === 'gen') {
                // Vector director = n1 x n2
                let A1 = getVal('al_' + prefix + '_g_a1'), B1 = getVal('al_' + prefix + '_g_b1'), C1 = getVal('al_' + prefix + '_g_c1');
                let A2 = getVal('al_' + prefix + '_g_a2'), B2 = getVal('al_' + prefix + '_g_b2'), C2 = getVal('al_' + prefix + '_g_c2');
                return [ B1*C2 - C1*B2, C1*A2 - A1*C2, A1*B2 - B1*A2 ];
            }
        }

        if(btnCalc) {
            btnCalc.addEventListener('click', function() {
                let vr = getDir('r');
                let vs = getDir('s');

                let modR2 = vr[0]*vr[0] + vr[1]*vr[1] + vr[2]*vr[2];
                let modS2 = vs[0]*vs[0] + vs[1]*vs[1] + vs[2]*vs[2];

                let resBox = document.getElementById('al_result_container');
                let mathBox = document.getElementById('al_res_math');

                if (modR2 === 0 || modS2 === 0) {
                    mathBox.innerHTML = `<p style="color: #c62828;"><strong>Error:</strong> Una de las rectas tiene un vector director nulo \((0,0,0)\).<br>Si usaste la ecuación general, revisa que los planos no sean paralelos.</p>`;
                } else {
                    let modR = Math.sqrt(modR2);
                    let modS = Math.sqrt(modS2);
                    let dotAbs = Math.abs(vr[0]*vs[0] + vr[1]*vs[1] + vr[2]*vs[2]);

                    let cosAlpha = dotAbs / (modR * modS);
                    cosAlpha = Math.max(-1, Math.min(1, cosAlpha));
                    let angleRad = Math.acos(cosAlpha);
                    let angleDeg = angleRad * (180 / Math.PI);

                    let deg = Math.floor(angleDeg);
                    let minFloat = (angleDeg - deg) * 60;
                    let min = Math.floor(minFloat);
                    let sec = Math.round((minFloat - min) * 60);
                    if (sec === 60) { sec = 0; min += 1; }
                    if (min === 60) { min = 0; deg += 1; }

                    let rootR_tex = (modR % 1 === 0) ? modR : `\\sqrt{${modR2}}`;
                    let rootS_tex = (modS % 1 === 0) ? modS : `\\sqrt{${modS2}}`;
                    let prodInt = Math.sqrt(modR2 * modS2);
                    let rootProd_tex = (prodInt % 1 === 0) ? prodInt : `\\sqrt{${modR2 * modS2}}`;

                    let mathAng = `\\[ \\cos(\\alpha) = \\dfrac{|\\vec{v_r} \\cdot \\vec{v_s}|}{|\\vec{v_r}| \\cdot |\\vec{v_s}|} = \\dfrac{${dotAbs}}{${rootR_tex} \\cdot ${rootS_tex}} \\]`;
                    mathAng += `\\[ \\alpha = \\arccos\\left( \\dfrac{${dotAbs}}{${rootProd_tex}} \\right) \\approx ${angleDeg.toFixed(2)}^\\circ \\]`;
                    mathAng += `\\[ \\alpha = ${deg}^\\circ\\ ${min}'\\ ${sec}'' \\]`;

                    mathBox.innerHTML = mathAng;
                }

                resBox.style.display = 'block';
                renderMath(resBox);
            });
        }

        if(btnClear) {
            btnClear.addEventListener('click', function() {
                document.querySelectorAll('#al-wrapper .al-inp').forEach(i => i.value = '');
                document.getElementById('al_result_container').style.display = 'none';
            });
        }
    }

    setTimeout(bindEvents, 200);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

