(function() {
    function bindEvents() {
        // Gestión de los selectores para mostrar/ocultar inputs
        function setupSelect(selId, prefix) {
            let sel = document.getElementById(selId);
            if(sel) {
                sel.addEventListener('change', function(e) {
                    document.getElementById(prefix + 'gen').style.display = 'none';
                    document.getElementById(prefix + 'vecs').style.display = 'none';
                    document.getElementById(prefix + e.target.value).style.display = 'flex';
                });
            }
        }
        setupSelect('ap_sel_p1', 'ap_p1_');
        setupSelect('ap_sel_p2', 'ap_p2_');

        let btnCalc = document.getElementById('ap_btn_calc');
        let btnClear = document.getElementById('ap_btn_clear');

        function getVal(id) {
            let el = document.getElementById(id);
            if (!el || el.value.trim() === '') return 0;
            let val = parseFloat(el.value);
            return isNaN(val) ? 0 : val;
        }

        function renderMath(container) {
            if (typeof MathJax !== 'undefined') {
                if (MathJax.typesetPromise) {
                    MathJax.typesetPromise([container]);
                } else if (MathJax.Hub) {
                    MathJax.Hub.Queue(["Typeset", MathJax.Hub, container]);
                }
            }
        }

        // Extrae el vector normal de los planos
        function getNormal(prefix) {
            let type = document.getElementById('ap_sel_' + prefix).value;
            if (type === 'gen') {
                return [ getVal('ap_' + prefix + '_A'), getVal('ap_' + prefix + '_B'), getVal('ap_' + prefix + '_C') ];
            } else if (type === 'vecs') {
                let u = [ getVal('ap_' + prefix + '_ux'), getVal('ap_' + prefix + '_uy'), getVal('ap_' + prefix + '_uz') ];
                let v = [ getVal('ap_' + prefix + '_vx'), getVal('ap_' + prefix + '_vy'), getVal('ap_' + prefix + '_vz') ];
                // Producto vectorial para obtener el vector normal
                return [ u[1]*v[2] - u[2]*v[1], u[2]*v[0] - u[0]*v[2], u[0]*v[1] - u[1]*v[0] ];
            }
        }

        if(btnCalc) {
            btnCalc.addEventListener('click', function() {
                let n1 = getNormal('p1');
                let n2 = getNormal('p2');

                let modN1_2 = n1[0]*n1[0] + n1[1]*n1[1] + n1[2]*n1[2];
                let modN2_2 = n2[0]*n2[0] + n2[1]*n2[1] + n2[2]*n2[2];

                let resBox = document.getElementById('ap_result_container');
                let mathBox = document.getElementById('ap_res_math');

                if (modN1_2 === 0 || modN2_2 === 0) {
                    mathBox.innerHTML = `<p style="color: #c62828;"><strong>Error:</strong> Uno de los planos tiene un vector normal nulo \((0,0,0)\).<br>Revisa los datos introducidos.</p>`;
                } else {
                    let modN1 = Math.sqrt(modN1_2);
                    let modN2 = Math.sqrt(modN2_2);
                    let dotAbs = Math.abs(n1[0]*n2[0] + n1[1]*n2[1] + n1[2]*n2[2]);

                    let cosAlpha = dotAbs / (modN1 * modN2);
                    cosAlpha = Math.max(-1, Math.min(1, cosAlpha));
                    let angleRad = Math.acos(cosAlpha);
                    let angleDeg = angleRad * (180 / Math.PI);

                    let deg = Math.floor(angleDeg);
                    let minFloat = (angleDeg - deg) * 60;
                    let min = Math.floor(minFloat);
                    let sec = Math.round((minFloat - min) * 60);
                    if (sec === 60) { sec = 0; min += 1; }
                    if (min === 60) { min = 0; deg += 1; }

                    let rootN1_tex = (modN1 % 1 === 0) ? modN1 : `\\sqrt{${modN1_2}}`;
                    let rootN2_tex = (modN2 % 1 === 0) ? modN2 : `\\sqrt{${modN2_2}}`;
                    let prodInt = Math.sqrt(modN1_2 * modN2_2);
                    let rootProd_tex = (prodInt % 1 === 0) ? prodInt : `\\sqrt{${modN1_2 * modN2_2}}`;

                    let mathAng = `\\[ \\cos(\\alpha) = \\dfrac{|\\vec{n}_1 \\cdot \\vec{n}_2|}{|\\vec{n}_1| \\cdot |\\vec{n}_2|} = \\dfrac{${dotAbs}}{${rootN1_tex} \\cdot ${rootN2_tex}} \\]`;
                    mathAng += `\\[ \\alpha = \\arccos\\left( \\dfrac{${dotAbs}}{${rootProd_tex}} \\right) \\approx ${angleDeg.toFixed(2)}^\\circ \\]`;
                    mathAng += `\\[ \\alpha = ${deg}^\\circ\\ ${min}'\\ ${sec}'' \\]`;

                    mathBox.innerHTML = mathAng;
                }

                resBox.style.display = 'block';
                renderMath(resBox);
            });
        }

        if(btnClear) {
            btnClear.addEventListener('click', function() {
                document.querySelectorAll('#ap-wrapper .ap-inp').forEach(i => i.value = '');
                document.getElementById('ap_result_container').style.display = 'none';
            });
        }
    }

    setTimeout(bindEvents, 200);
})();
</script>
