</div>
</div>
</div>
<!-- Contenedor Plano pi -->
<div style="background-color: #fff; padding: 15px; border-radius: 6px; border: 1px solid #ffcc80; flex: 1; min-width: 300px; display: flex; flex-direction: column; align-items: center;">
<div style="margin-bottom: 15px; width: 100%; text-align: center;"><label style="font-weight: bold; color: #e65100; font-size: 1.1em;">Plano \(\pmb{\pi}\): </label><select id="arp_sel_p" class="arp-select">
<option value="gen">Ecuación General (Implícita)</option>
<option value="vecs">Punto y dos vectores</option>
</select></div>
<!-- p: General -->
<div id="arp_p_gen" class="arp-input-group" style="display: flex; align-items: center; justify-content: center;">
<div style="white-space: nowrap;"><input type="number" id="arp_p_A" class="arp-inp" />\(x +\) <input type="number" id="arp_p_B" class="arp-inp" />\(y +\) <input type="number" id="arp_p_C" class="arp-inp" />\(z +\) <input type="number" id="arp_p_D" class="arp-inp" />\(= 0\)</div>
</div>
<!-- p: Vectores -->
<div id="arp_p_vecs" class="arp-input-group" style="display: none; align-items: center; justify-content: center; flex-direction: column; gap: 8px;">
<div><span>\(P(\)</span> <input type="number" id="arp_p_px" class="arp-inp" placeholder="px" />, <input type="number" id="arp_p_py" class="arp-inp" placeholder="py" />, <input type="number" id="arp_p_pz" class="arp-inp" placeholder="pz" /> <span>\()\)</span></div>
<div><span>\(\vec{u} = (\)</span> <input type="number" id="arp_p_ux" class="arp-inp" placeholder="ux" />, <input type="number" id="arp_p_uy" class="arp-inp" placeholder="uy" />, <input type="number" id="arp_p_uz" class="arp-inp" placeholder="uz" /> <span>\()\)</span></div>
<div><span>\(\vec{w} = (\)</span> <input type="number" id="arp_p_vx" class="arp-inp" placeholder="wx" />, <input type="number" id="arp_p_vy" class="arp-inp" placeholder="wy" />, <input type="number" id="arp_p_vz" class="arp-inp" placeholder="wz" /> <span>\()\)</span></div>
