<style>
    /* Blindaje CSS */
    #arp-wrapper .arp-inp { width: 48px !important; padding: 6px 4px !important; text-align: center !important; border: 2px solid #ffb74d !important; border-radius: 4px !important; font-size: 1em !important; background-color: #fff !important; color: #333 !important; transition: border-color 0.2s !important; margin: 0 2px !important; }
