    #arp-wrapper .arp-select:focus { border-color: #e65100 !important; }

    #arp-wrapper .arp-btn-calc { display: inline-block; background-color: #f57c00 !important; color: #ffffff !important; border: 2px solid #f57c00 !important; padding: 10px 22px !important; cursor: pointer !important; border-radius: 5px !important; font-weight: bold !important; font-size: 1.05em !important; margin: 0 5px !important; user-select: none; transition: all 0.2s !important; }
    #arp-wrapper .arp-btn-calc:hover { background-color: #e65100 !important; border-color: #e65100 !important; }

