    #arp-wrapper .arp-btn-clear:hover { background-color: #fff3e0 !important; border-color: #e65100 !important; color: #e65100 !important; }
</style>
<script>
(function() {
    function bindEvents() {
        function setupSelect(selId, prefix) {
            let sel = document.getElementById(selId);
            if(sel) {
                sel.addEventListener('change', function(e) {
                    if (prefix === 'arp_r_') {
                        document.getElementById('arp_r_vec').style.display = 'none';
                        document.getElementById('arp_r_par').style.display = 'none';
                        document.getElementById('arp_r_gen').style.display = 'none';
                    } else {
                        document.getElementById('arp_p_gen').style.display = 'none';
                        document.getElementById('arp_p_vecs').style.display = 'none';
                    }
                    document.getElementById(prefix + e.target.value).style.display = 'flex';
                });
            }
        }
        setupSelect('arp_sel_r', 'arp_r_');
        setupSelect('arp_sel_p', 'arp_p_');

        let btnCalc = document.getElementById('arp_btn_calc');
        let btnClear = document.getElementById('arp_btn_clear');

        function getVal(id) {
            let el = document.getElementById(id);
            if (!el || el.value.trim() === '') return 0;
            let val = parseFloat(el.value);
            return isNaN(val) ? 0 : val;
        }

        function renderMath(container) {
            if (typeof MathJax !== 'undefined') {
                if (MathJax.typesetPromise) {
                    MathJax.typesetPromise([container]);
                } else if (MathJax.Hub) {
                    MathJax.Hub.Queue(["Typeset", MathJax.Hub, container]);
                }
            }
        }

        function getLineDir() {
            let type = document.getElementById('arp_sel_r').value;
            if (type === 'vec') {
                return [ getVal('arp_r_vx'), getVal('arp_r_vy'), getVal('arp_r_vz') ];
            } else if (type === 'par') {
                return [ getVal('arp_r_par_vx'), getVal('arp_r_par_vy'), getVal('arp_r_par_vz') ];
            } else if (type === 'gen') {
                let A1 = getVal('arp_r_g_a1'), B1 = getVal('arp_r_g_b1'), C1 = getVal('arp_r_g_c1');
                let A2 = getVal('arp_r_g_a2'), B2 = getVal('arp_r_g_b2'), C2 = getVal('arp_r_g_c2');
                return [ B1*C2 - C1*B2, C1*A2 - A1*C2, A1*B2 - B1*A2 ];
            }
        }

        function getPlaneNormal() {
            let type = document.getElementById('arp_sel_p').value;
            if (type === 'gen') {
                return [ getVal('arp_p_A'), getVal('arp_p_B'), getVal('arp_p_C') ];
            } else if (type === 'vecs') {
                let u = [ getVal('arp_p_ux'), getVal('arp_p_uy'), getVal('arp_p_uz') ];
                let v = [ getVal('arp_p_vx'), getVal('arp_p_vy'), getVal('arp_p_vz') ];
                return [ u[1]*v[2] - u[2]*v[1], u[2]*v[0] - u[0]*v[2], u[0]*v[1] - u[1]*v[0] ];
            }
        }

        if(btnCalc) {
            btnCalc.addEventListener('click', function() {
                let vr = getLineDir();
                let np = getPlaneNormal();

                let modVr2 = vr[0]*vr[0] + vr[1]*vr[1] + vr[2]*vr[2];
                let modNp2 = np[0]*np[0] + np[1]*np[1] + np[2]*np[2];

                let resBox = document.getElementById('arp_result_container');
                let mathBox = document.getElementById('arp_res_math');

                if (modVr2 === 0 || modNp2 === 0) {
                    mathBox.innerHTML = `<p style="color: #c62828;"><strong>Error:</strong> Se detectó un vector nulo \((0,0,0)\). Verifica los coeficientes para asegurar que la recta o el plano son válidos.</p>`;
                } else {
                    let modVr = Math.sqrt(modVr2);
                    let modNp = Math.sqrt(modNp2);
                    let dotAbs = Math.abs(vr[0]*np[0] + vr[1]*np[1] + vr[2]*np[2]);

                    let sinAlpha = dotAbs / (modVr * modNp);
                    sinAlpha = Math.max(-1, Math.min(1, sinAlpha));
                    let angleRad = Math.asin(sinAlpha);
                    let angleDeg = angleRad * (180 / Math.PI);

                    let deg = Math.floor(angleDeg);
                    let minFloat = (angleDeg - deg) * 60;
                    let min = Math.floor(minFloat);
                    let sec = Math.round((minFloat - min) * 60);
                    if (sec === 60) { sec = 0; min += 1; }
                    if (min === 60) { min = 0; deg += 1; }

                    let rootVr_tex = (modVr % 1 === 0) ? modVr : `\\sqrt{${modVr2}}`;
                    let rootNp_tex = (modNp % 1 === 0) ? modNp : `\\sqrt{${modNp2}}`;
                    let prodInt = Math.sqrt(modVr2 * modNp2);
                    let rootProd_tex = (prodInt % 1 === 0) ? prodInt : `\\sqrt{${modVr2 * modNp2}}`;

                    let mathAng = `\\[ \\text{sen}(\\alpha) = \\dfrac{|\\vec{v}_r \\bullet \\vec{n}_\\pi|}{|\\vec{v}_r| \\cdot |\\vec{n}_\\pi|} = \\dfrac{${dotAbs}}{${rootVr_tex} \\cdot ${rootNp_tex}} \\]`;
                    mathAng += `\\[ \\alpha = \\text{arcsen}\\left( \\dfrac{${dotAbs}}{${rootProd_tex}} \\right) \\approx ${angleDeg.toFixed(2)}^\\circ \\]`;
                    mathAng += `\\[ \\alpha = ${deg}^\\circ\\ ${min}'\\ ${sec}'' \\]`;

                    mathBox.innerHTML = mathAng;
                }

                resBox.style.display = 'block';
                renderMath(resBox);
            });
        }

        if(btnClear) {
            btnClear.addEventListener('click', function() {
                document.querySelectorAll('#arp-wrapper .arp-inp').forEach(i => i.value = '');
                document.getElementById('arp_result_container').style.display = 'none';
            });
        }
    }

    setTimeout(bindEvents, 200);
})();
</script>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

